"""specs_s200039.py - Sonnet-w2 family Q (generated by mkfamQ.py): F1 (fastcall hook that also records edx), 0x45c4b0 and INIT record the SEH chain; b is zero about half of the cases; the
allocator returns 0 sometimes. Fake outer SEH records 0-2; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, clear_hooks, hook_rec, seh_record, seh_chain


def _mk(f1, init):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        p = r.choice([0, rnd(c, 0x100), rnd(c, 0x100), rnd(c, 0x100)])
        sr = seh_record(c, 2)

        def side(emu, k):
            emu.calllog.append(('edx', emu.reg('edx')))
            sr(emu, k)
        hook_rec(c, f1, 2, ret=r.getrandbits(32), pop=8, this=True, side=side)
        hook_rec(c, 0x45c4b0, 1, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, init, 3, ret=r.getrandbits(32), pop=12, this=True, side=seh_record(c, 2))
        return [r.getrandbits(32), r.getrandbits(32), r.getrandbits(32), r.choice([0, 0, 1, r.getrandbits(32)])]
    return gen


S(0x44e9c0, 'GUESS famQ 0x44e9c0', 'fastcall', None, ret='eax', gen=_mk(0x44e830, 0x44e900), note='batch200039')
S(0x451a90, 'GUESS famQ 0x451a90', 'fastcall', None, ret='eax', gen=_mk(0x4518e0, 0x4519a0), note='batch200039')
S(0x45a680, 'GUESS famQ 0x45a680', 'fastcall', None, ret='eax', gen=_mk(0x45a470, 0x45a530), note='batch200039')
S(0x4ee6a0, 'GUESS famQ 0x4ee6a0', 'fastcall', None, ret='eax', gen=_mk(0x4ee0e0, 0x4ee1b0), note='batch200039')
S(0x4f99b0, 'GUESS famQ 0x4f99b0', 'fastcall', None, ret='eax', gen=_mk(0x4f9720, 0x4f97f0), note='batch200039')
